var fs = require("fs");
var path = require("path");
var utils = require("./utils");
var constants = require("./../constants");
var cluster = require("cluster");

var writeStream, fd, logsDir, bytesWritten, baseDir;
var newLine = "\n",
    space = " ",
    emptyStr = "",
    underScore = "_";
var maxSize = 10 * 1024 * 1024; // 10 MB
var maxLogFiles = 5;
var levels = {
    DEBUG: 5,
    INFO: 4,
    WARNING: 3,
    CRITICAL: 2,
    ERROR: 1,
    OFF: 0
};

function init(configInstance) {
    const dir = configInstance && configInstance.getBaseDir();
    if (utils.isEmpty(dir)) {
        console.error("[APM] Base directory is not set in the configuration.");
        writeStream = process.stdout;
        return;
    }
    baseDir = dir;
    var date = new Date();
    var month = date.getMonth() + 1;
    var dateStr =
        date.getDate() +
        underScore +
        month +
        underScore +
        date.getFullYear() +
        underScore +
        date.getHours() +
        underScore +
        date.getMinutes() +
        underScore +
        date.getSeconds() +
        underScore +
        date.getMilliseconds() +
        underScore +
        process.pid;
    try {
        logsDir = path.join(baseDir, "logs");
        if (!fs.existsSync(logsDir)) {
            try {
                fs.mkdirSync(logsDir);
            } catch (dirErr) {
                console.error(`[APM] Failed to create logs directory:  ${dirErr.message}`, dirErr);
                writeStream = process.stdout;
                return;
            }
        }
        cleanLogFiles();
        var filePath = path.join(
            logsDir,
            "apminsight_agent_logs_" + dateStr + ".log"
        );
        try {
            fd = fs.openSync(filePath, "a");
            if (writeStream) {
                try {
                    writeStream.end();
                } catch (streamEndErr) {
                    console.error(`[APM] Failed to close previous write stream: ${streamEndErr.message}`, streamEndErr);
                }
            }
            writeStream = fs.createWriteStream(null, { flags: "a", fd: fd });
            writeStream.on("error", handleStreamError);
            bytesWritten = 0;
        } catch (fileErr) {
            console.error(`[APM] Failed to open log file: ${fileErr.message}`, fileErr);
            writeStream = process.stdout;
        }
    } catch (err) {
        console.error(
            `[APM] Failed to create apminsight agent logs at ${filePath || 'unknown path'}:`,
            err
        );
    }
}

function parseCreationTimeFromFilename(filename) {
    try {
        let prefix = "apminsight_agent_logs_";
        let suffix = ".log";
        if (!filename.startsWith(prefix) || !filename.endsWith(suffix)) {
            return null;
        }
        let middle = filename.slice(prefix.length, -suffix.length);
        let parts = middle.split(underScore);
        // parts: [day, month, year, hour, min, sec, ms, pid]
        if (parts.length < 7) {
            return null;
        }
        let day = parseInt(parts[0], 10),
            month = parseInt(parts[1], 10) - 1, // Date month is 0-indexed
            year = parseInt(parts[2], 10),
            hour = parseInt(parts[3], 10),
            min = parseInt(parts[4], 10),
            sec = parseInt(parts[5], 10),
            ms = parseInt(parts[6], 10);
        let ts = new Date(year, month, day, hour, min, sec, ms).getTime();
        return isNaN(ts) ? null : ts;
    } catch (e) {
        return null;
    }
}

function cleanLogFiles() {

    // when multiple worker processes try to delete files simultaneously
    // cluster.isMaster was deprecated from Node.js v16.x,
    let isPrimary = cluster.isPrimary !== undefined ? cluster.isPrimary : cluster.isMaster;
    if (!isPrimary) {
        return;
    }
    // Use readdirSync so cleanup completes before init() creates the new log file.
    // With async readdir, the new file was already created by the time the callback
    // fired, causing one extra file to be deleted and leaving only maxLogFiles-1 files.
    let files;
    try {
        files = fs.readdirSync(logsDir);
    } catch (err) {
        return;
    }
    let logFiles = files.filter(function (file) {
        return file.startsWith("apminsight_agent_logs_") && file.endsWith(".log");
    });
    // Reserve one slot for the new file about to be created in init(),
    // so the final count after creation stays at maxLogFiles.
    if (logFiles.length < maxLogFiles) {
        return;
    }
    let filesSorted = logFiles.map(function (file) {
        let filePath = path.join(logsDir, file);
        let ts = parseCreationTimeFromFilename(file);
        if (ts === null) {
            try {
                ts = fs.statSync(filePath).birthtimeMs;
            } catch (e) {
                ts = 0;
            }
        }
        return { filePath: filePath, ts: ts };
    });
    // Sort descending — newest first
    filesSorted.sort(function (a, b) {
        return b.ts - a.ts;
    });
    // Delete everything beyond maxLogFiles - 1 to leave room for the new file
    filesSorted.slice(maxLogFiles - 1).forEach(function (entry) {
        removeFile(entry.filePath);
    });
}

function removeFile(filePath) {
    fs.unlink(filePath, function (err) {
        if (err) {
            return;
        }
        log(constants.info, "old log file deleted: " + filePath);
    });
}

function error(message, e) {
    write(constants.error, message, getStackTrace, e);
}

function logAndThrowError(level, message, obj) {
    log(level, message, obj);
    throw new Error(message);
}

function debug(message, obj) {
    log(constants.debug, message, obj);
}

function info(message, obj) {
    log(constants.info, message, obj);
}

function critical(message, obj) {
    log(constants.critical, message, obj);
}

function warning(message, obj) {
    log(constants.warning, message, obj);
}

function log(level, message, obj) {
    write(level, message, stringify, obj);
}

/* eslint-disable no-unused-vars */
function handleStreamError(error) {
    //need to handle error
}
/* eslint-enable no-unused-vars */

function write(level, message, toStr, obj) {

    if (!writeStream) {
        console.error("[APM] WriteStream is not initialized.");
        return;
    }
    if (!isAllowed(levels[level])) {
        return;
    }

    if (bytesWritten > maxSize) {
        if (!global.apmInsightAgentInstance) {
            console.error("[APM] Write max size exceeded and no agent instance available to reinitialize.");
            return;
        }
        init(global.apmInsightAgentInstance.getConfig());
    }
    var writeStr =
        getTime() +
        space +
        "[" +
        level +
        "]" +
        space +
        message +
        space +
        toStr(obj) +
        newLine;
    bytesWritten += Buffer.byteLength(writeStr);
    writeStream.write(writeStr);
}

function isAllowed(level) {
    if (level <= getLogConf()) {
        return true;
    }
    return false;
}

function getLogConf() {
    if (!global.apmInsightAgentInstance) {
        return levels.DEBUG;
    }
    if (levels[utils.getGenericThreshold().getLogLevel()]) {
        return levels[utils.getGenericThreshold().getLogLevel()];
    }
    return levels.DEBUG;
}

function getTime() {
    var date = new Date();
    var month = date.getMonth() + 1;
    return (
        "[" +
        date.getDate() +
        "/" +
        month +
        "/" +
        date.getFullYear() +
        space +
        date.getHours() +
        ":" +
        date.getMinutes() +
        ":" +
        date.getSeconds() +
        "]"
    );
}

function getStackTrace(e) {
    try {
        if (utils.isEmpty(e)) {
            return emptyStr;
        }
        return e.stack;
    } catch (e) {
        return emptyStr;
    }
}

function stringify(obj) {
    try {
        if (utils.isEmpty(obj)) {
            return emptyStr;
        }
        return JSON.stringify(obj);
    } catch (e) {
        return emptyStr;
    }
}

module.exports = {
    init: init,
    debug: debug,
    info: info,
    warning: warning,
    critical: critical,
    error: error,
    logAndThrowError: logAndThrowError
};
